package main

import (
	"os"
	"runtime"
	"testing"
	"time"
)

// TestBigDeck checks a 25k-note / 50k-card package (generated by testdecks/big.py).
func TestBigDeck(t *testing.T) {
	if _, err := os.Stat("testdata/big.apkg"); err != nil {
		t.Skip("big deck not present")
	}
	runtime.GC()
	var before, after runtime.MemStats
	runtime.ReadMemStats(&before)
	t0 := time.Now()
	dir := t.TempDir()
	p, err := OpenPackage("testdata/big.apkg", dir, nil)
	if err != nil {
		t.Fatal(err)
	}
	conv := time.Since(t0)
	runtime.ReadMemStats(&after)
	if len(p.Cards) != 50000 || len(p.Notes) != 25000 || len(p.Decks) != 11 {
		t.Fatalf("cards %d notes %d decks %d", len(p.Cards), len(p.Notes), len(p.Decks))
	}
	p.Close()
	t1 := time.Now()
	p2, err := OpenPackage("testdata/big.apkg", dir, nil)
	if err != nil {
		t.Fatal(err)
	}
	defer p2.Close()
	reopen := time.Since(t1)
	runtime.GC()
	var held runtime.MemStats
	runtime.ReadMemStats(&held)
	prog := &Progress{Cards: map[string]*CardState{}}
	t2 := time.Now()
	s := NewSession(p2, prog, p2.CardsIn(""), 20, 200, time.Now())
	sess := time.Since(t2)
	if s.Total != 20 {
		t.Fatalf("session %d", s.Total)
	}
	t.Logf("convert %v (allocated %d MB total), reopen from cache %v, heap held %d MB, session build %v",
		conv.Round(time.Millisecond), (after.TotalAlloc-before.TotalAlloc)>>20, reopen.Round(time.Millisecond), held.HeapAlloc>>20, sess.Round(time.Millisecond))
	if f := p2.Fields(p2.Cards[49999].Note); len(f) != 2 || len(f[1]) < 50 {
		t.Fatalf("last note fields %q", f)
	}
}
